function home(){const tasks=[['photos','Change a banner','Fresh photo. Fresh first impression.','banners'],['price','Update a price','Change prices or add a discount.','prices'],['plus','Add a product','Put something new on your shelf.','new-product'],['services','Edit a service','Update what you do, and what it costs.','services'],['text','Edit website text','Say it your way, in a few clicks.','content'],['menu','Change the menu','Make everything easy to find.','menu']];const waiting=inbox.filter(r=>r.status==='new').length;return `${heading('YOUR STORE. YOUR WAY.','Your website, in your hands.','A new photo. A new price. A whole new offer. Start with what you want to change.','<span class="welcome-tag"><i></i> English workspace</span>')}
 <div class="overview-strip" data-tour="home-counts"><div><strong>${data.products.length}</strong><span>products on your shelf<small>CURRENT SITE INVENTORY</small></span></div><div><strong>${data.categories.length}</strong><span>shop categories<small>WITH THEIR SUBCATEGORIES</small></span></div><div><strong>${waiting}</strong><span>new orders & bookings<small>WAITING FOR YOU</small></span></div></div>
 <div class="home-columns"><section data-tour="home-tasks"><div class="section-caption"><h2>What would you like to change?</h2><span>Pick a task to get started ↙</span></div><div class="task-grid">${tasks.map((t,i)=>`<button class="task-card ${i===0?'featured':''}" data-task="${t[3]}"><span class="task-icon">${icon(t[0])}</span><span class="arrow">↗</span><b>${t[1]}</b><small>${t[2]}</small></button>`).join('')}</div></section><section class="site-card-column"><div class="section-caption"><h2>Your website</h2><span>DRAFT PREVIEW</span></div><div class="site-card" data-tour="home-preview"><div class="browser-chrome" aria-hidden="true"><i></i><i></i><i></i><span>MOTO MARKET / HOME</span></div>${sitePreview()}<div class="site-card-foot"><span>Everything here is editable.</span><button data-route="website" data-sub="content">Open website editor ↗</button></div></div><div class="safe-note">${icon('shield')}<span>Make yourself at home. Save a draft, check how it looks, then publish when you’re ready.</span></div></section></div>
 <div class="bottom-columns"><section class="panel" data-tour="home-latest"><div class="panel-head"><h2>Your latest changes</h2><button data-action="review">See all →</button></div>${changes.length?changes.slice(-3).reverse().map(c=>`<div class="history-row">${esc(c.label)}<small>${esc(c.detail)}${c.detail?' · ':''}Saved as draft</small></div>`).join(''):`<div class="empty-inline">${icon('clock')}<span>A clean slate. Make your first change.<small>Your edits will appear here before you publish.</small></span></div>`}</section><section class="panel"><div class="panel-head"><h2>One place for everything.</h2></div><button class="guide-link" data-route="photos"><b>01</b><span>Every photo, banner & icon</span><span>↗</span></button><button class="guide-link" data-route="products" data-sub="categories"><b>02</b><span>Every category & collection</span><span>↗</span></button><button class="guide-link" data-route="settings"><b>03</b><span>Your details, hours & links</span><span>↗</span></button></section></div>
 <div class="bottom-columns home-structure-row">${renderStructureCard(ctx)}${lowStockPanel()}</div>`;}
function lowStockPanel(){const low=data.products.filter(p=>stockState(p)==='low'),out=data.products.filter(p=>stockState(p)==='out'),n=low.length+out.length,rows=[...out,...low].slice(0,5);return `<section class="panel low-stock" data-tour="home-lowstock"><div class="panel-head"><h2>${n?`${n} product${n===1?'':'s'} low or out of stock`:'Stock looks good'}</h2>${n?'<button data-stock-filter="low">See all →</button>':''}</div>${n?`<div class="low-stock__chips"><button class="btn tiny ghost" data-stock-filter="low">${low.length} running low</button><button class="btn tiny ghost" data-stock-filter="out">${out.length} sold out</button></div><ul class="low-stock__list">${rows.map(p=>`<li><button type="button" data-edit="product" data-id="${esc(p.id)}"><img src="${esc(imageUrl(p.image))}" alt=""><span>${esc(p.name)}<small>${stockState(p)==='out'?'Sold out':esc(`${p.quantity} left · warn at ${p.lowStock??3}`)}</small></span></button></li>`).join('')}</ul>`:`<div class="empty-inline">${icon('check')}<span>Nothing is running low.<small>Set a quantity on a product and I'll warn you here when it runs low.</small></span></div>`}</section>`;}
