function publishing(){return heading('YOUR STORIES. YOUR STYLE.','Pages & Posts','Build a page with HTML and CSS, or write a post using your store’s ready-made template.')+`<div class="toolbar"><h2>Website pages</h2>${addButton('page','Create page')}</div>${listOf('page',data.pages,{sortable:false})}<div class="toolbar"><h2>Posts</h2>${addButton('post','Create post')}</div>${data.posts.length?listOf('post',data.posts):`<div class="empty-inline mascot-empty">${mascotHtml(ctx,32)}<span>Your first story starts here. Add a title, cover picture and the words. We take care of the layout.</span></div>`}<p class="small-note">After publishing, link to a new page or post from Website → Website menu.</p>`;}
function editStaff(id){const s=staffList.find(s=>s.user_id===id);if(!s)return;modal('MANAGE STAFF ACCESS',`<h2>Edit ${esc(s.display_name)}</h2><form id="staff-edit-form" data-id="${s.user_id}">${field('name','Staff name',s.display_name,'text','required')}${field('username','Username',s.username,'text','required pattern="[a-z][a-z0-9_-]{2,29}"')}${select('role','Role',s.role,[['owner','Administrator — full access'],['editor','Content Manager — website content'],['service','Service Coordinator — requests']])}${check('canPublish','Allow this Content Manager to publish',s.can_publish)}${field('password','New password (leave empty to keep current)','','password','minlength="14" autocomplete="new-password"')}<p class="small-note">Existing passwords are never displayed. Enter a new password to reset access.</p><button class="btn primary">Save access changes</button></form>`);}
