const categoryName=id=>data.categories.find(c=>c.id===id)?.name||id;
const imageUrl=ref=>ref?.startsWith('media:')?mediaUrls[ref.slice(6)]||'':ref?.startsWith('assets/')?'../'+ref:ref||'';
// Toast: a popover="manual" element so it sits above open dialogs. While a modal dialog is open it lives inside
// that dialog (a modal makes everything outside it inert), and it is re-shown whenever a dialog opens or closes.
const toastEl=$('#toast');let undoOffer=false;
function topModal(){return [...document.querySelectorAll('dialog[open]')].filter(d=>{try{return d.matches(':modal');}catch{return true;}}).pop()||null;}
function showToastLayer(){if(!toastEl.classList.contains('show'))return;const host=topModal()||document.body;if(toastEl.parentElement!==host)host.appendChild(toastEl);if(toastEl.showPopover){try{toastEl.hidePopover();}catch{}try{toastEl.showPopover();}catch{}}}
function hideToast(){toastEl.classList.remove('show');clearTimeout(toastTimer);setTimeout(()=>{if(!toastEl.classList.contains('show')){try{toastEl.hidePopover?.();}catch{}}},220);}
function toast(message,{undo:offer=false}={}){delete toastEl.dataset.demo;undoOffer=!!offer&&undo.size>0&&['owner','editor'].includes(staff?.role);$('#toast-text').textContent=message;$('#toast-undo').hidden=!undoOffer;if(undoOffer)$('#toast-undo').textContent='Undo';toastEl.classList.add('show');showToastLayer();clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,undoOffer?8000:5000);}
new MutationObserver(muts=>{if(!toastEl.isConnected)document.body.appendChild(toastEl);if(muts.some(m=>m.target.tagName==='DIALOG'))queueMicrotask(showToastLayer);}).observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:['open']});
function fillIcons(){$$('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));}
function heading(k,title,description,action=''){return `<div class="page-heading" data-tour="page-title"><div><span class="eyebrow red">${esc(k)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="heading-actions">${explainButtonHtml(ctx)}${action}</div></div>`;}
function modal(kicker,html){$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=html;const title=$('#modal-body h2');if(title)title.id='modal-title';if(!$('#modal').open)$('#modal').showModal();}
// Maps a validateContent message to the editor field it is about, so the error line can point at it.
const FIELD_ERRORS=[[/sale|discount/i,'#field-sale'],[/regular price|whole BDT price|product price/i,'#field-price'],[/SKU/,'#field-sku'],[/tags/i,'#field-tags'],[/low-stock/i,'#field-lowStock'],[/subcategor/i,'#field-subcategory,[data-subs]'],[/gallery/i,'[data-gallery]'],[/data sheet/i,'#field-datasheetLink'],[/compatib|vehicle|universal|bikes, cars/i,'#field-fitment'],[/colour/i,'#colour-editor'],[/menu destination/i,'#field-target'],[/destination/i,'#field-destination'],[/address|slug/i,'#field-slug'],[/section|button destination/i,'[data-sec-editor]'],[/brand group/i,'#field-group'],[/category/i,'#field-category'],[/name/i,'#field-name']];
function editorError(message){const line=$('#editor-error');if(!line)return false;line.innerHTML=message?`${mascotHtml(ctx,32)}<span><b>Something needs fixing</b>${esc(message)}</span>`:'';line.hidden=!message;$$('.field-error').forEach(x=>x.classList.remove('field-error'));if(!message)return true;const hit=FIELD_ERRORS.find(([re])=>re.test(message));const el=hit&&$(hit[1],$('#editor-body'));if(el){const box=el.closest('.field,[data-subs],[data-gallery],[data-sec-editor],#colour-editor')||el;box.classList.add('field-error');box.closest('details')?.setAttribute('open','');box.scrollIntoView({block:'center',behavior:'smooth'});(el.matches('input,select,textarea')?el:box.querySelector('input,select,textarea'))?.focus({preventScroll:true});}return true;}
function errorMessage(error){const message=error?.detail||error?.message||'Unable to save. Please try again.';if(!($('#editor').open&&editorError(message)))toast(message);if(error?.code==='CONFLICT'){undo.clear();undoOffer=false;$('#toast-undo').hidden=true;if($('#toast-text').textContent!==message)hideToast();modal('NEWER CHANGES FOUND','<h2>Your draft needs a refresh.</h2><p>Another staff member saved first. Your form stays open so you can copy your changes. Close it and reload the latest draft before trying again.</p><button class="btn primary" data-action="reload">Reload latest draft</button>');}}
async function run(task){if(busy)return;busy=true;document.body.classList.add('is-busy');$$('button[type="submit"]').forEach(b=>b.disabled=true);try{await task();}catch(e){errorMessage(e);}finally{busy=false;document.body.classList.remove('is-busy');$$('button[type="submit"]').forEach(b=>b.disabled=b.hasAttribute('data-locked'));}}
// Drafts saved before subcategories became records hold plain names that the website shows A-Z. Sorting them once
// here keeps that order when they turn into records, so the first publish does not reshuffle the menu.
function sortLegacyChildren(doc){for(const c of doc?.categories||[])if(Array.isArray(c.children)&&c.children.some(x=>typeof x==='string'))c.children=[...c.children].sort((a,b)=>String(a?.name??a).localeCompare(String(b?.name??b),'en',{sensitivity:'base'}));}
async function load(){const r=await admin('load');undo.clear();staff=r.staff;inbox=r.requests||[];media=r.media||[];mediaUrls=r.mediaUrls||{};sortLegacyChildren(r.draft?.content);data=r.draft?.content;if(data){data.posts||=[];withContentDefaults(data);}version=r.draft?.version;changes=r.draft?.changes||[];published=r.live?.content;revisions=r.revisions||[];if(!data)route='requests';$('#login-screen').hidden=true;document.body.classList.remove('signed-out');$('.owner-label').textContent=roleName(staff.role);$('.profile-name').textContent=staff.display_name;$('.demo-bar span').innerHTML='<b>CONNECTED WORKSPACE</b> Save a draft. Preview it. Publish when ready.';$('.publish-button').hidden=!data;$('.preview-button').hidden=!data;render();startTour();}
function startTour(){if(tour)return;tour=createTour(ctx);setInterval(()=>{const onStep=tour.running()&&tour.current()?.anchor==='undo-toast';if(!onStep){if(toastEl.dataset.demo){delete toastEl.dataset.demo;$('#toast-undo').hidden=true;hideToast();}return;}if(!toastEl.classList.contains('show')){toast(undo.size?'Every save shows Undo here for a few seconds.':'After each save, Undo appears here for a few seconds.');$('#toast-undo').hidden=false;$('#toast-undo').textContent='Undo';toastEl.dataset.demo='1';clearTimeout(toastTimer);}},400);if(!tour.resume())setTimeout(()=>{if(!$('#editor').open&&!$('#modal').open)tour.greet();},600);}
// Every save keeps the previous document on the undo stack; the success toast offers Undo.
async function save(next,key,label,detail=''){const list=clone(changes);const item={key,label,detail};const i=list.findIndex(c=>c.key===key);if(i<0)list.push(item);else list[i]=item;const before={doc:data,changes:changes};const r=await admin('save',{version,content:next,changes:list});data=next;version=r.version;changes=list;undo.push(label,before);render();refreshPreviewFrame();toast((label?label+'. ':'')+'Draft saved. Your live website changes when you publish.',{undo:true});}
function refreshPreviewFrame(){const frame=$('#preview-window iframe');if(frame)frame.src='../index.html?preview=draft&version='+version;}
async function undoLast(){const entry=undo.peek();if(!entry||!data)return;hideToast();await run(async()=>{const r=await admin('save',{version,content:entry.before.doc,changes:entry.before.changes});undo.pop();data=entry.before.doc;version=r.version;changes=entry.before.changes;render();refreshPreviewFrame();toast('Undone: '+entry.label+'. Your draft is back as it was.');});}
function routeOf(hash){return String(hash||'').replace(/^#/,'').split('?')[0];}
function go(to,sub){if($('#modal').open)$('#modal').close();if($('#editor').open){if(!editorState?.demo&&isDirty()){confirmDiscard(ctx).then(ok=>{if(ok){closeEditorNow();go(to,sub);}});return;}closeEditorNow();}const was=[route,view,productsView,servicesView].join('|');route=labels[to]?to:'home';if(!data&&route!=='settings')route='requests';if(sub){if(to==='website')view=sub;if(to==='products')productsView=sub;if(to==='services')servicesView=sub;}if(routeOf(location.hash)!==route)location.hash=route;setMenu(false);render();window.scrollTo(0,0);}
function setMenu(open){const sb=$('#sidebar'),btn=$('.mobile-menu');if(open)document.documentElement.style.setProperty('--drawer-top',Math.max(0,Math.round($('.topbar').getBoundingClientRect().bottom))+'px');sb.classList.toggle('open',open);btn?.setAttribute('aria-expanded',String(open));}
function updateMenuCount(){const b=$('.mobile-menu');if(!b)return;const n=inbox.filter(r=>r.status==='new').length;if(n)b.dataset.count=n>99?'99+':String(n);else delete b.dataset.count;b.setAttribute('aria-label',n?`Toggle navigation (${n} new request${n===1?'':'s'})`:'Toggle navigation');}
function render(){const available=data?Object.entries(labels):Object.entries(labels).filter(([id])=>id==='requests'||id==='settings');$('#navigation').innerHTML=available.map(([id,name])=>`<button data-route="${id}" data-tour="nav-${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='requests'?`<span class="nav-meta">${inbox.filter(r=>r.status==='new').length}</span>`:''}</button>`).join('');$('#crumb-title').textContent=labels[route];$('#change-count').textContent=changes.length;productList?.destroy();productList=null;$('#main').innerHTML=({home,products,services,website,photos,requests,settings,publishing}[route]||home)();fillIcons();updateMenuCount();bindPage();}
// Wires the ui modules on the page that render() just drew.
function bindPage(){const main=$('#main');if(!data)return;bindRecordList(ctx,main);const pl=$('#product-list',main);if(pl)productList=mountProductList(ctx,pl,{hash:location.hash});if($('[data-lay-root],[data-lay-add],[data-lay-open]',main))bindLayout(ctx,main);if($('[data-bg-root]',main))bindBrandGroups(ctx,main);if($('[data-ph-root]',main))bindPhotos(ctx,main);if($('[data-io-root]',main))bindIo(ctx,main);}
function sitePreview(source=data){const b=source.banners.find(b=>b.visible),s=source.services.filter(s=>s.visible).slice(0,3);return `<div class="mini-site"><div class="mini-header" aria-hidden="true"><img src="${esc(imageUrl(source.settings.logo))}" alt="${esc(source.settings.name)}"><span>PARTS · SERVICE · GEAR</span></div>${b?`<div class="mini-banner"><img src="${esc(imageUrl(b.image))}" alt="${esc(b.alt)}"><button class="edit-overlay" data-edit="banner" data-id="${b.id}">${icon('edit')} Change banner</button></div>`:''}<div class="mini-intro" aria-hidden="true"><span class="eyebrow">YOUR STORE. ALWAYS UP TO DATE.</span><h3>${esc(source.settings.slogan)}</h3><div class="mini-blocks">${s.map(x=>`<div><img src="${esc(imageUrl(x.image))}" alt="">${esc(x.name)}</div>`).join('')}</div></div></div>`;}
function addButton(type,label){return `<button class="btn primary" data-edit="${type}" data-id="new" data-tour="add-button">${icon('plus')} ${esc(label)}</button>`;}
function tabs(items,current,target){return '<div class="subtabs" role="tablist" data-tour="tabs">'+items.map(([id,title])=>`<button data-route="${target}" data-sub="${id}" data-tour="tab-${id}" role="tab" aria-selected="${current===id}" class="${current===id?'active':''}">${title}</button>`).join('')+'</div>';}
