// Category editor "Also add to website": which links already exist (those boxes are greyed out).
function websiteLinks(id){return {menu:data.menu.some(m=>m.target===id),card:data.blocks.some(b=>b.kind==='category'&&b.target===id),section:(data.sections||[]).some(s=>s.page==='shop'&&s.source?.category===id)};}
