function editorActions(type,p,isNew,demo){const lock=demo?' disabled data-locked title="Finish the tour first"':'';const del=(!isNew||demo)&&type!=='identity'&&COLLECTIONS[type]&&canDelete(type,staff.role,isNew?null:p);const dup=(!isNew||demo)&&type!=='identity'&&COLLECTIONS[type]&&canDuplicate(type,staff.role,isNew?null:p);const another=ADD_ANOTHER.has(type);return `<div class="sheet-actions__left">${del?`<button type="button" class="btn danger" data-editor-delete data-tour="editor-delete" ${isNew?'disabled title="Delete is there once the item is saved"':''}>Delete</button>`:''}${dup?`<button type="button" class="btn ghost" data-editor-duplicate data-tour="editor-duplicate" ${isNew?'disabled title="Save first, then you can copy it"':''}>Duplicate</button>`:''}</div><div class="sheet-actions__right"><button type="button" class="btn ghost" data-action="close-editor">Cancel</button>${another?`<button type="submit" class="btn ghost" name="intent" value="another" data-tour="editor-save-another"${lock}>Save & add another</button>`:''}<button type="submit" class="btn primary" name="intent" value="save" data-tour="editor-save"${lock}>${demo?'Finish the tour first':'Save draft'} <span>→</span></button></div>`;}
