function searchResults(q){const query=q.trim().toLowerCase();const all=[...Object.entries(labels).map(([id,name])=>({id,name,route:id})),...Object.entries(collections).flatMap(([type,key])=>(data?.[key]||[]).map(x=>({id:x.id,name:x.name||x.title||'',type})))];const found=all.filter(x=>x.name.toLowerCase().includes(query)).slice(0,20).map(x=>`<button class="search-result" ${x.route?`data-route="${x.route}"`:`data-edit="${x.type}" data-id="${esc(x.id)}"`}>${esc(x.name)}<small>${esc(x.type?EDITOR_NAME[x.type]||x.type:'Workspace')} ↗</small></button>`).join('');const chapters=query.length>1&&staff?chapterResultsHtml(ctx,searchChapters(query,{role:staff.role,canPublish:staff.role==='owner'||!!staff.can_publish}).slice(0,3)):'';$('#global-results').innerHTML=chapters+(found||(chapters?'':'<p>No matches found.</p>'));}
function openRequest(id){const r=inbox.find(x=>x.id===id);if(!r)return;const d=r.details;modal('REQUEST '+r.receipt,`<h2>${esc(r.customer_name)}</h2><p>${esc(r.phone)} · ${esc(r.kind)}</p>${r.phone?`<a class="btn primary call-link" href="tel:${esc(String(r.phone).replace(/[^\d+]/g,''))}">Call ${esc(r.customer_name||r.phone)}</a>`:''}${d.address?`<p><b>Address:</b> ${esc(d.address)}</p>`:''}<p>${esc(d.vehicle||'')}</p><p><b>Customer note:</b> ${esc(d.notes||'No customer notes.')}</p>${d.items?d.items.map(i=>`<div class="review-row">${esc(i.name)}${i.colorName?' · '+esc(i.colorName):''} × ${i.quantity}<strong>${money(i.quantity*i.unitPriceMinor/100)}</strong></div>`).join('')+(d.deliveryMinor?`<div class="review-row">Delivery · ${esc(d.delivery||'')}<strong>${money(d.deliveryMinor/100)}</strong></div>`:'')+`<h3>Total ${money(d.totalMinor/100)}</h3><button class="btn ghost" type="button" data-invoice="${r.id}">Print invoice ↗</button>`:`<p>${esc(d.services?.map(s=>s.name).join(', '))}</p><p>Preferred: ${esc(d.date||'Any day')} · ${esc(d.slot||'Any time')}</p>`}<form id="request-form" data-id="${r.id}" data-tour="request-status">${select('status','Request status',r.status,['new','contacted','confirmed','completed','cancelled'])}${textarea('notes','Staff notes (private)',r.staff_notes)}<button class="btn primary">Save request update</button></form>`);}
async function team(){const r=await admin('staff-list');staffList=r.staff;modal('STAFF ACCESS',`<h2>Your team.</h2><div class="team-list" data-tour="team-list">${r.staff.map(s=>`<div class="section-row"><div><h3>${esc(s.display_name)}</h3><p>${esc(s.username)} · ${esc(roleName(s.role))} · ${s.active?'Active':'Disabled'}</p></div><button class="btn ghost" data-staff-edit="${s.user_id}">Edit access</button>${s.user_id!==staff.user_id?`<button class="btn ghost" data-staff-toggle="${s.user_id}" data-disabled="${s.active}">${s.active?'Disable':'Enable'}</button>`:''}</div>`).join('')}</div><h3>Add a staff member</h3><form id="staff-form">${field('name','Staff name','','text','required')}${field('username','Username','','text','pattern="[a-z][a-z0-9_-]{2,29}" required autocomplete="off"')}${field('password','Temporary password','','password','minlength="14" required autocomplete="new-password"')}${select('role','Access level','editor',[['editor','Content Manager — edit website'],['service','Service Coordinator — requests'],['owner','Administrator — full access']])}${check('canPublish','Allow this editor to publish',false)}<p class="small-note">Share the username and temporary password privately. They can change their password in Store settings.</p><button class="btn primary">Create staff account</button></form>`);}
function showLogin(message=''){document.body.classList.add('signed-out');$('#login-screen').hidden=false;$('#login-message').textContent=message;}
$('#login-form').addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),username=String(f.get('username')).trim().toLowerCase();const {error}=await db.auth.signInWithPassword({email:username+'@staff.motomarket.invalid',password:String(f.get('password'))});if(error){$('#login-message').textContent='Check your username and password, then try again.';return;}await load();e.target.reset();});});
$('#editor-form').addEventListener('submit',saveEditor);
$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});
$('#editor').addEventListener('click',e=>{if(e.target===$('#editor'))closeEditor();const jump=e.target.closest('[data-jump]');if(jump){e.preventDefault();const s=$('#'+CSS.escape(jump.dataset.jump));if(s){s.open=true;s.scrollIntoView({block:'start',behavior:'smooth'});}}if(e.target.closest('[data-editor-delete]')&&editorState&&!editorState.isNew){const {type,id}=editorState;deleteFlow(ctx,type,id).then(r=>{if(r)closeEditorNow();});}if(e.target.closest('[data-editor-duplicate]')&&editorState&&!editorState.isNew){const {type,id}=editorState;closeEditor().then(ok=>{if(ok)duplicateFlow(ctx,type,id);});}});
document.addEventListener('submit',e=>{const id=e.target.id;if(['settings-form','orders-settings-form','invoice-settings-form','booking-slots-form','service-categories-form','password-form','request-form','staff-form','staff-edit-form'].includes(id)){e.preventDefault();run(async()=>{const f=new FormData(e.target);if(id==='settings-form'){const next=clone(data);for(const [k,v] of f)next.settings[k]=String(v).trim();await save(next,'settings','Updated store details');}if(id==='orders-settings-form')await save(readOrderSettings(e.target),'delivery-settings','Updated delivery & order settings');if(id==='invoice-settings-form')await save(readInvoiceSettings(e.target),'invoice-settings','Updated invoice & payment details');if(id==='booking-slots-form')await save(readBookingSlots(e.target),'booking-slots','Updated booking time slots');if(id==='service-categories-form'){const next=clone(data),list=lineList(f.get('categories'));if(!list.length)throw new Error('Keep at least one service category.');next.services.forEach(s=>{if(list.includes(s.category))return;const cand=next.serviceCategories.length===list.length?list[next.serviceCategories.indexOf(s.category)]:'';s.category=cand&&!next.serviceCategories.includes(cand)?cand:list[0];});next.serviceCategories=list;await save(next,'service-categories','Updated service categories');}if(id==='password-form'){const {error}=await db.auth.updateUser({password:String(f.get('password'))});if(error)throw error;e.target.reset();toast('Your password has been changed.');}if(id==='request-form'){const r=inbox.find(r=>r.id===e.target.dataset.id);await admin('request-update',{id:r.id,version:r.version,status:f.get('status'),notes:f.get('notes')});await load();$('#modal').close();toast('Request updated.');}if(id==='staff-edit-form'){await admin('staff-update',{userId:e.target.dataset.id,name:f.get('name'),username:f.get('username'),password:f.get('password'),role:f.get('role'),canPublish:f.has('canPublish')});await team();toast('Staff access updated.');}if(id==='staff-form'){await admin('staff-create',{name:f.get('name'),username:f.get('username'),password:f.get('password'),role:f.get('role'),canPublish:f.has('canPublish')});await team();toast('Staff account created.');}});}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='field-blockTarget'&&editorState?.type==='block'){const [kind,target]=e.target.value.split(':');$('#block-subcategories').innerHTML=blockSubcategories(target,[]);if(editorState.isNew){const record=(kind==='category'?data.categories:data.services).find(p=>p.id===target);if(record?.image)setPicture('image',record.image);}}});
$('#pds-upload').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;run(async()=>{const r=await uploadDocument(file);media.unshift(r.media);mediaUrls[r.media.id]=r.url;setDatasheet('media:'+r.media.id);toast('Data sheet uploaded. Save the product, then publish to show it on the website.');});});
$('#image-upload').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const key=e.target.dataset.picture;run(async()=>{const r=await ctxUpload(file);if(key&&editorState){setPicture(key,r.ref);toast('Picture uploaded. Save this draft to use it.');}else{render();toast('Picture added to your library.');}});});
$('#toast').addEventListener('click',e=>{if(e.target.closest('#toast-undo')){if(toastEl.dataset.demo)return;undoLast();}else if(e.target.closest('[data-toast-close]'))hideToast();});
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-route]');if(!b)return;const d=b.dataset;
 if(d.route){$('#modal').close();go(d.route,d.sub);return;}if(d.task){const map={banners:['website','banners'],prices:['products','products'],services:['services','services'],content:['website','content'],menu:['website','menu']};if(d.task==='new-product')openEditor('product','new');else go(...map[d.task]);return;}
 if(d.edit){$('#modal').close();openEditor(d.edit,d.id);return;}if(d.order){run(async()=>{const next=clone(data),list=next[collections[d.order]],i=Number(d.index),j=i+Number(d.dir);if(d.order==='block'){if(!moveCard(list,d.orderId,Number(d.dir)))return;}else{if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];}await save(next,d.order+'-order','Reordered '+collections[d.order]);});return;}
 if(e.target.closest('[data-datasheet-upload]')){$('#pds-upload').value='';$('#pds-upload').click();return;}if(e.target.closest('[data-datasheet-clear]')){setDatasheet('');return;} if(d.invoice){const r=inbox.find(x=>x.id===d.invoice);if(r){const win=window.open('','_blank');run(async()=>{let store;try{store=data?.settings||(await live()).content.settings;}catch(err){win?.close();throw err;}openInvoice({receipt:r.receipt,createdAt:r.created_at,name:r.customer_name,phone:r.phone,address:r.details.address,items:r.details.items,delivery:r.details.delivery,deliveryMinor:r.details.deliveryMinor,totalMinor:r.details.totalMinor,store},win);});}return;} if(d.pictureClear){setPicture(d.pictureClear,'');return;}if(d.pictureChoose){chooseImage(d.pictureChoose);return;}if(d.pictureUpload){$('#image-upload').dataset.picture=d.pictureUpload;$('#image-upload').value='';$('#image-upload').click();return;}if(b.hasAttribute('data-choose-clear')){const cb=chooseCallback;chooseCallback=null;$('#modal').close();cb?.('');return;}if(d.stockFilter){$('#modal').close();window.history.replaceState(window.history.state,'','#products?stock='+encodeURIComponent(d.stockFilter)+'&sort=stock');go('products','products');window.scrollTo(0,0);const pc=$('#main [data-pl-count]')||$('#main h1');if(pc){pc.tabIndex=-1;pc.focus({preventScroll:true});}return;}
 if(d.device){$('#preview-window').classList.toggle('phone',d.device==='phone');return;}if(d.request){openRequest(d.request);return;}if(d.restore){modal('RESTORE WEBSITE VERSION',`<h2>Restore this version?</h2><p>This replaces both the saved draft and the public website. The current publication remains in history, so you can bring it back.</p><button class="btn ghost" data-action="close-modal">Keep current version</button> <button class="btn primary" data-confirm-restore="${d.restore}">Restore version</button>`);return;}if(d.confirmRestore){run(async()=>{await admin('restore',{version,revision:d.confirmRestore});await load();$('#modal').close();toast('Website restored to the selected version.');});return;}
 if(d.staffEdit){editStaff(d.staffEdit);return;}if(d.staffToggle){run(async()=>{await admin('staff-disable',{userId:d.staffToggle,disabled:d.disabled==='true'});await team();});return;}
 if(d.removeColour){editorState.record.colors=editorState.record.colors.filter(c=>c.id!==d.removeColour);$(`[data-colour-row="${CSS.escape(d.removeColour)}"]`).remove();return;}const action=d.action;if(action==='add-product-model'){addProductModel();return;}if(action==='add-colour'){const c={id:'colour-'+crypto.randomUUID(),name:'',hex:'#dc1238',stock:'In stock',image:''};editorState.record.colors||=[];editorState.record.colors.push(c);$('#colour-editor').insertAdjacentHTML('beforeend',colourRow(c));$(`[name="colour-name-${c.id}"]`).focus();return;}if(action==='menu')setMenu(!$('#sidebar').classList.contains('open'));if(action==='close-editor'){closeEditor();}if(action==='close-modal')$('#modal').close();if(action==='help')help();if(action==='search')search();if(action==='review')review();if(action==='publish')publish();if(action==='preview')preview();if(action==='reload')run(async()=>{await load();$('#modal').close();closeEditorNow();toast('Latest saved content loaded.');});if(action==='staff')run(team);if(action==='upload-library'){$('#image-upload').dataset.picture='';$('#image-upload').value='';$('#image-upload').click();}if(action==='signout')run(async()=>{await db.auth.signOut();data=null;showLogin();});
});
window.addEventListener('hashchange',()=>{if(staff){const next=routeOf(location.hash);if(labels[next]&&next!==route)go(next);}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&staff&&!$('#editor').open&&!$('#modal').open){e.preventDefault();search();}});
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar,.mobile-menu,#tour-layer'))setMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){setMenu(false);$('.mobile-menu')?.focus();}});
window.addEventListener('scroll',()=>{if($('#sidebar').classList.contains('open'))setMenu(true);},{passive:true});
db.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){staff=null;data=null;showLogin();}});
route=labels[routeOf(location.hash)]?routeOf(location.hash):'home';fillIcons();
// The shared context every control-room ui module receives (plan 2.7). Getters keep it current after each load/save.
async function ctxUpload(file){const r=await upload(file);if(!media.some(m=>m.id===r.media.id))media.unshift(r.media);mediaUrls[r.media.id]=r.url;return {...r,ref:'media:'+r.media.id};}
async function ctxUploadDocument(file){const r=await uploadDocument(file);if(!media.some(m=>m.id===r.media.id))media.unshift(r.media);mediaUrls[r.media.id]=r.url;return {...r,ref:'media:'+r.media.id};}
function ctxModal(opts,html){if(typeof opts==='string')return modal(opts,html||'');const {title='',body='',mascot=false}=opts||{};modal(String(title).toUpperCase(),(mascot?`<div class="modal-mascot">${mascotHtml(ctx,56)}</div>`:'')+body);}
export const ctx={get data(){return data;},save:async(next,label)=>{try{await save(next,'ui:'+label,label);}catch(e){if(e?.code==='CONFLICT')errorMessage(e);throw e;}},go,openEditor,modal:ctxModal,toast,esc,icon,imageUrl,chooseImage,upload:ctxUpload,uploadDocument:ctxUploadDocument,admin,get role(){return staff?.role;},get staffId(){return staff?.user_id;},get canPublish(){return staff?.role==='owner'||!!staff?.can_publish;},openTeam:()=>run(team),get media(){return media;},get mediaUrls(){return mediaUrls;},get editorType(){return editorState?.type;},validate:checkDocument,field,select,check,textarea,photoField,setMenu,undo};
try{const {data:{session}}=await db.auth.getSession();if(session)await load();else showLogin();}catch(e){showLogin(e.message);}

let syncBusy=false;
async function syncWorkspace(){if(!staff||busy||syncBusy||document.hidden||$('#editor').open||$('#modal').open)return;syncBusy=true;try{const r=await admin('sync');staff=r.staff;inbox=r.requests||[];if(data&&r.version!==version){await load();toast('The latest saved changes from your team are now loaded.');}else if(route==='requests')render();else{const counter=$('[data-route="requests"] .nav-meta');if(counter)counter.textContent=inbox.filter(x=>x.status==='new').length;updateMenuCount();}}catch(e){if(/access|sign in/i.test(e.message)){staff=null;data=null;showLogin(e.message);}}finally{syncBusy=false;}}
setInterval(syncWorkspace,30000);document.addEventListener('visibilitychange',syncWorkspace);window.addEventListener('online',syncWorkspace);

function updateCompatibilityFields(){const method=$('[name=fitment]')?.value,models=$('[data-compatible-models]'),types=$('[data-universal-types]');if(models)models.hidden=method==='Universal';if(types)types.hidden=method!=='Universal';}
function addProductModel(){
 const brand=$('[name=new-model-brand]').value.trim(),name=$('[name=new-model-name]').value.trim(),type=$('[name=new-model-type]').value;
 const status=$('[data-model-added]');
 if(!brand||!name){status.textContent='Enter the manufacturer and model name first.';return;}
 const existing=[...data.vehicles,...editorState.newVehicles||[]].find(v=>v.visible!==false&&v.type===type&&v.brand.toLowerCase()===brand.toLowerCase()&&v.name.toLowerCase()===name.toLowerCase());
 const model=existing||{id:'vehicle-'+crypto.randomUUID(),type,brand,name,visible:true};
 if(!existing){editorState.newVehicles||=[];editorState.newVehicles.push(model);const label=document.createElement('label');label.innerHTML=`<input type="checkbox" name="vehicleIds" value="${esc(model.id)}"> ${esc(brand+' '+name)} <small>· ${type==='bike'?'Bike':'Car'}</small>`;$('[data-compatible-models]').append(label);}
 const checkbox=$(`[name=vehicleIds][value="${CSS.escape(model.id)}"]`);checkbox.checked=true;checkbox.closest('label').hidden=false;
 $('[name=fitment]').value='Selected vehicles';$('[data-model-check-search]').value='';$$('label',$('[data-compatible-models]')).forEach(l=>l.hidden=false);updateCompatibilityFields();
 status.textContent=(existing?'Selected: ':'Added & selected: ')+model.brand+' '+model.name+'. Save the product to keep this change.';
 $('[name=new-model-name]').value='';
}
document.addEventListener('change',e=>{if(e.target.name==='quantity'||e.target.name?.startsWith('colour-quantity-')){if(e.target.value==='')return;const stock=e.target.name==='quantity'?$('[name=stock]'):$(`[name="colour-stock-${e.target.name.slice(16)}"]`);if(stock)stock.value=Number(e.target.value)===0?'Out of stock':'In stock';}});
document.addEventListener('change',e=>{if(e.target.name==='fitment')updateCompatibilityFields();});document.addEventListener('change',e=>{if(e.target.matches('[name=vehicleIds]')&&e.target.checked){const f=$('[name=fitment]');if(f&&f.value!=='Selected vehicles'){f.value='Selected vehicles';updateCompatibilityFields();}}});document.addEventListener('input',e=>{if(e.target.matches('[data-model-check-search]')){$$('label',e.target.closest('fieldset')).forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(e.target.value.toLowerCase()));}});
